#!/usr/bin/env bash
# Build paper/main.pdf from the tables and figures generated by `python -m cegqa.cli report`.
# Usage: scripts/build_paper.sh [results_dir]   (default: results)
set -euo pipefail
cd "$(dirname "$0")/.."
RESULTS="${1:-results}"
mkdir -p paper/tables paper/figures
cp "$RESULTS"/tables/*.tex paper/tables/
cp "$RESULTS"/figures/*.pdf paper/figures/
cd paper
if command -v tectonic >/dev/null; then
  tectonic -X compile main.tex
else
  latexmk -pdf -interaction=nonstopmode main.tex
fi
echo "built paper/main.pdf"
